from decimal import Decimal
from typing import Any


def map_invoice_response_to_invoice(source: dict[str, Any]) -> dict[str, Any]:
    return {
        "total": Decimal(str(round(source["cents"] / 100.0))) if source["cents"] > 0 else Decimal("0"),
        "half": source["cents"] / 2.0,
        "size": len(source["name"]) + 1,
        "gap": abs(source["delta"]),
        "small": min(source["cents"], 10),
    }

import java.math.BigDecimal;

public final class InvoiceResponseMapper {

    private InvoiceResponseMapper() {
    }

    public static Invoice toInvoice(InvoiceResponse source) {
        if (source == null) {
            return null;
        }
        return new Invoice(
                source.getCents() > 0 ? BigDecimal.valueOf(Math.round((double) source.getCents() / 100.0)) : new BigDecimal("0"),
                (double) source.getCents() / 2.0,
                (long) (source.getName().length() + 1),
                Math.abs(source.getDelta()),
                Math.min(source.getCents(), 10)
        );
    }
}

