using System;

public static class InvoiceResponseMappings
{
    public static Invoice ToInvoice(this InvoiceResponse source)
    {
        ArgumentNullException.ThrowIfNull(source);
        return new Invoice
        {
            Total = source.Cents > 0 ? (decimal)(Math.Round((double)source.Cents / 100.0)) : 0m,
            Half = (double)source.Cents / 2.0,
            Size = source.Name.Length + 1,
            Gap = Math.Abs(source.Delta),
            Small = Math.Min(source.Cents, 10),
        };
    }
}

using System;
using AutoMapper;

public class InvoiceResponseProfile : Profile
{
    public InvoiceResponseProfile()
    {
        CreateMap<InvoiceResponse, Invoice>()
            .ForMember(dest => dest.Total, opt => opt.MapFrom(src => src.Cents > 0 ? (decimal)(Math.Round((double)src.Cents / 100.0)) : 0m))
            .ForMember(dest => dest.Half, opt => opt.MapFrom(src => (double)src.Cents / 2.0))
            .ForMember(dest => dest.Size, opt => opt.MapFrom(src => src.Name.Length + 1))
            .ForMember(dest => dest.Gap, opt => opt.MapFrom(src => Math.Abs(src.Delta)))
            .ForMember(dest => dest.Small, opt => opt.MapFrom(src => Math.Min(src.Cents, 10)));
    }
}

