func mapInvoiceResponseToInvoice(source InvoiceResponse) Invoice {
	return Invoice{
		Total: func() float64 {
			if source.Cents > 0 {
				return math.Round(float64(source.Cents) / 100.0)
			}
			return 0.0
		}(),
		Half: float64(source.Cents) / 2.0,
		Size: int64(len([]rune(source.Name))) + 1,
		Gap: max(source.Delta, -source.Delta),
		Small: min(source.Cents, 10),
	}
}

