use rust_decimal::Decimal;
use crate::models::{Invoice, InvoiceResponse};

impl From<&InvoiceResponse> for Invoice {
    fn from(source: &InvoiceResponse) -> Self {
        Self {
            total: if source.cents > 0 { Decimal::try_from((source.cents as f64 / 100.0).round()).expect("number out of range") } else { Decimal::from(0) },
            half: source.cents as f64 / 2.0,
            size: source.name.chars().count() as i64 + 1,
            gap: source.delta.abs(),
            small: source.cents.min(10),
        }
    }
}

